const items = $input.all();

const DEFAULT_MANDATORY_AGENTS = [
  "GST_AGENT",
  "PAN_AGENT",
  "UDYAM_AGENT",
  "FINANCIAL_AGENT",
  "DOCUMENT_FORENSICS_AGENT",
  "EXPERIENCE_AGENT",
  "ENTITY_RESOLUTION_AGENT",
  "RISK_INTELLIGENCE_AGENT"
];

return items.map(item => {
  const data = item.json.body || item.json;
  const errors = [];

  const requestId = data.request_id || "REQ-FINAL-DEMO";
  const tenderId = data.tender_id || "TENDER-FINAL-DEMO";
  const bidderId = data.bidder_id || "BIDDER-FINAL-DEMO";
  const bidderName = (data.bidder_name || "ABC Technologies Pvt Ltd").toString().trim();

  let agentResults = data.agent_results;
  if (agentResults !== undefined && agentResults !== null) {
    if (!Array.isArray(agentResults)) {
      errors.push("Field 'agent_results' must be an array");
      agentResults = [];
    }
  } else {
    agentResults = [];
  }

  const policy = data.compliance_policy || {};
  let mandatory = policy.mandatory_agents;
  if (!Array.isArray(mandatory) || mandatory.length === 0) {
    // If policy doesn't specify mandatory agents, check if required_agents was provided in root
    if (Array.isArray(data.required_agents) && data.required_agents.length > 0) {
      mandatory = data.required_agents;
    } else {
      mandatory = DEFAULT_MANDATORY_AGENTS;
    }
  }

  const allowReview = policy.allow_review_status !== undefined ? Boolean(policy.allow_review_status) : false;
  const maxReviewScore = typeof policy.maximum_review_risk_score === 'number' ? policy.maximum_review_risk_score : 49;

  const filteredMandatory = mandatory
    .map(a => a.toUpperCase())
    .filter(a => a !== 'FINAL_COMPLIANCE_AGENT');

  return {
    json: {
      request_id: requestId,
      tender_id: tenderId,
      bidder_id: bidderId,
      bidder_name: bidderName,
      agent_results: agentResults,
      compliance_policy: {
        mandatory_agents: filteredMandatory,
        allow_review_status: allowReview,
        maximum_review_risk_score: maxReviewScore
      },
      valid_schema: errors.length === 0,
      validation_errors: errors,
      raw_input: data
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;
  if (!data.valid_schema) return { json: data };

  const results = data.agent_results || [];
  const mandatory = data.compliance_policy?.mandatory_agents || [];

  const resultMap = new Map();
  results.forEach(r => {
    if (r && r.agent) {
      resultMap.set(r.agent.toUpperCase(), r);
    }
  });

  const missingMandatory = [];
  const evaluatedList = [];

  mandatory.forEach(agentKey => {
    if (resultMap.has(agentKey)) {
      const res = resultMap.get(agentKey);
      if (res.status === 'NOT_EXECUTED') {
        missingMandatory.push(agentKey);
      }
      evaluatedList.push({
        agent: agentKey,
        ...res
      });
    } else {
      missingMandatory.push(agentKey);
      evaluatedList.push({
        agent: agentKey,
        status: 'NOT_EXECUTED',
        confidence: 0.0,
        risk_level: 'HIGH',
        issues: [`Mandatory agent '${agentKey}' is missing from submission`]
      });
    }
  });

  // Also preserve non-mandatory supplemental agent results if present
  results.forEach(r => {
    if (r && r.agent && !mandatory.includes(r.agent.toUpperCase())) {
      evaluatedList.push(r);
    }
  });

  return {
    json: {
      ...data,
      evaluated_agents: evaluatedList,
      missing_mandatory_agents: missingMandatory,
      coverage_complete: missingMandatory.length === 0
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;
  if (!data.valid_schema) return { json: data };

  const agents = data.evaluated_agents || [];
  const mandatory = new Set(data.compliance_policy?.mandatory_agents || []);

  const passed = [];
  const failed = [];
  const errors = [];
  const missing = [];
  const lowConfidence = [];
  const reviewItems = [];

  let riskScore = 0;
  let riskLevel = 'LOW';

  agents.forEach(a => {
    const aName = a.agent;
    const isMandatory = mandatory.has(aName);
    const status = (a.status || '').toUpperCase();
    const issues = Array.isArray(a.issues) ? a.issues : (a.issues ? [String(a.issues)] : []);

    // Capture risk score from Risk Intelligence Agent if present
    if (aName === 'RISK_INTELLIGENCE_AGENT') {
      if (a.evidence && typeof a.evidence.risk_score === 'number') {
        riskScore = a.evidence.risk_score;
        riskLevel = a.evidence.risk_level || (riskScore >= 50 ? 'HIGH' : (riskScore >= 20 ? 'MEDIUM' : 'LOW'));
      }
    }

    if (isMandatory) {
      if (status === 'VERIFIED') {
        passed.push(aName);
        // Check confidence
        if (typeof a.confidence === 'number' && a.confidence < 0.70) {
          lowConfidence.push({ agent: aName, confidence: a.confidence });
          reviewItems.push(`${aName} returned low verification confidence (${a.confidence} < 0.70)`);
        }
      } else if (status === 'NOT_VERIFIED') {
        failed.push({
          agent: aName,
          status: 'NOT_VERIFIED',
          issues: issues.length > 0 ? issues : [`${aName} failed compliance criteria`]
        });
      } else if (status === 'ERROR') {
        errors.push({
          agent: aName,
          status: 'ERROR',
          issues: issues.length > 0 ? issues : [`${aName} encountered execution error`]
        });
        reviewItems.push(`${aName} encountered system error (ERROR)`);
      } else if (status === 'NOT_EXECUTED') {
        missing.push({
          agent: aName,
          status: 'NOT_EXECUTED',
          issues: issues.length > 0 ? issues : [`${aName} was not executed`]
        });
        reviewItems.push(`Mandatory agent ${aName} was not executed`);
      }
    }
  });

  return {
    json: {
      ...data,
      passed_requirements: passed,
      failed_requirements: failed,
      error_requirements: errors,
      missing_requirements: missing,
      low_confidence_requirements: lowConfidence,
      extracted_review_items: reviewItems,
      effective_risk_score: riskScore,
      effective_risk_level: riskLevel
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;
  if (!data.valid_schema) {
    return {
      json: {
        ...data,
        final_decision: data.compliance_policy?.allow_review_status ? 'REVIEW_REQUIRED' : 'NOT_QUALIFIED',
        decision_status: 'ERROR',
        decision_basis: data.validation_errors || ['Malformed input structure']
      }
    };
  }

  const policy = data.compliance_policy || {};
  const allowReview = policy.allow_review_status;

  const failed = data.failed_requirements || [];
  const errors = data.error_requirements || [];
  const missing = data.missing_requirements || [];
  const lowConf = data.low_confidence_requirements || [];
  const riskScore = data.effective_risk_score || 0;

  let decision = 'QUALIFIED';
  let status = 'QUALIFIED';
  const basis = [];

  // RULE PRECEDENCE:
  // 1. If any mandatory agent is NOT_VERIFIED -> definitive failure NOT_QUALIFIED
  if (failed.length > 0) {
    decision = 'NOT_QUALIFIED';
    status = 'NOT_QUALIFIED';
    failed.forEach(f => {
      basis.push(`${f.agent} failed verification (NOT_VERIFIED): ${f.issues.join('; ')}`);
    });
  }
  // 2. If any mandatory agent encountered an execution ERROR
  else if (errors.length > 0) {
    decision = allowReview ? 'REVIEW_REQUIRED' : 'NOT_QUALIFIED';
    status = decision;
    errors.forEach(e => {
      basis.push(`${e.agent} encountered system error (ERROR): ${e.issues.join('; ')}`);
    });
  }
  // 3. If any mandatory agent was NOT_EXECUTED or missing
  else if (missing.length > 0) {
    decision = allowReview ? 'REVIEW_REQUIRED' : 'NOT_QUALIFIED';
    status = decision;
    missing.forEach(m => {
      basis.push(`Mandatory agent ${m.agent} was not executed`);
    });
  }
  // 4. If Risk Score >= 50 points
  else if (riskScore >= 50) {
    decision = allowReview ? 'REVIEW_REQUIRED' : 'NOT_QUALIFIED';
    status = decision;
    basis.push(`Aggregated risk score (${riskScore}) exceeds safe threshold (>= 50)`);
  }
  // 5. If low confidence items exist and review is permitted
  else if (lowConf.length > 0 && allowReview) {
    decision = 'REVIEW_REQUIRED';
    status = 'REVIEW_REQUIRED';
    lowConf.forEach(c => {
      basis.push(`${c.agent} verification confidence (${c.confidence}) is below standard threshold (0.70)`);
    });
  }
  // 6. All mandatory requirements verified
  else {
    decision = 'QUALIFIED';
    status = 'QUALIFIED';
    basis.push('All mandatory verification agents returned VERIFIED');
    basis.push(`Risk score (${riskScore}) is below blocking threshold`);
  }

  return {
    json: {
      ...data,
      final_decision: decision,
      decision_status: status,
      decision_basis: basis
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;

  const agents = data.evaluated_agents || [];
  const mandatory = data.compliance_policy?.mandatory_agents || [];

  // Calculate deterministic confidence score
  let minConfidence = 1.0;
  agents.forEach(a => {
    if (mandatory.includes(a.agent) && typeof a.confidence === 'number') {
      if (a.confidence < minConfidence) minConfidence = a.confidence;
    }
  });

  let calculatedConfidence = minConfidence;
  if (data.final_decision === 'REVIEW_REQUIRED') {
    calculatedConfidence = Math.min(calculatedConfidence, 0.85);
  } else if (data.decision_status === 'ERROR') {
    calculatedConfidence = 0.0;
  }

  // Risk level mapping
  const score = data.effective_risk_score || 0;
  let riskLevel = 'LOW';
  if (score >= 50 || data.final_decision === 'NOT_QUALIFIED') {
    riskLevel = 'HIGH';
  } else if (score >= 20 || data.final_decision === 'REVIEW_REQUIRED') {
    riskLevel = 'MEDIUM';
  } else {
    riskLevel = 'LOW';
  }

  // Collect all issues across failed agents
  const issues = [];
  const failed = data.failed_requirements || [];
  failed.forEach(f => {
    f.issues.forEach(iss => issues.push(iss));
  });
  const errors = data.error_requirements || [];
  errors.forEach(e => {
    e.issues.forEach(iss => issues.push(iss));
  });

  return {
    json: {
      ...data,
      synthesized_confidence: Math.min(0.99, Math.max(0.0, Number(calculatedConfidence.toFixed(2)))),
      synthesized_risk_level: riskLevel,
      consolidated_issues: issues
    }
  };
});

const items = $input.all();

return items.map(item => {
  const data = item.json;

  const mandatory = data.compliance_policy?.mandatory_agents || [];
  const passed = data.passed_requirements || [];
  const failed = (data.failed_requirements || []).map(f => `${f.agent}: ${f.issues.join('; ')}`);
  const reviewItems = data.extracted_review_items || [];

  return {
    json: {
      agent: "FINAL_COMPLIANCE_AGENT",
      status: data.decision_status || data.final_decision || "QUALIFIED",
      confidence: data.synthesized_confidence !== undefined ? data.synthesized_confidence : 0.99,
      evidence: {
        mandatory_agents: mandatory,
        agents_evaluated: (data.evaluated_agents || []).length,
        passed_requirements: passed,
        failed_requirements: failed,
        review_items: reviewItems,
        risk_score: data.effective_risk_score || 0,
        decision_basis: data.decision_basis || []
      },
      issues: data.consolidated_issues || [],
      risk_level: data.synthesized_risk_level || "LOW",
      final_decision: data.final_decision || "QUALIFIED",
      timestamp: new Date().toISOString()
    }
  };
});

const items = $input.all();
return items.map(item => ({
  json: item.json
}));

const items = $input.all();
return items.map(item => ({
  json: {
    agent: "FINAL_COMPLIANCE_AGENT",
    status: "ERROR",
    confidence: 0.0,
    evidence: {
      error: "Final compliance agent encountered an unexpected execution failure",
      fallback_mode: true
    },
    issues: ["Final compliance evaluation failed safely"],
    risk_level: "HIGH",
    final_decision: "REVIEW_REQUIRED",
    timestamp: new Date().toISOString()
  }
}));
